   158|function safeTrimCS(value: unknown): string {
   159|  if (typeof value === 'string') {
   160|    return value.trim();
   161|  }
   162|  if (value == null) {
   163|    return '';
   164|  }
   165|  try {
   166|    return String(value).trim();
   167|  } catch {
   168|    return '';
   169|  }
   170|}
   171|
   172|function normalizeOutboundText(value: unknown): string {
   173|  if (typeof value === 'string') {
   174|    return value;
   175|  }
   176|
   177|  if (typeof value === 'number' || typeof value === 'boolean') {
   178|    return String(value);
   179|  }
   180|
   181|  if (value == null) {
   182|    return '';
   183|  }
   184|
   185|  try {
   186|    return String(value);
   187|  } catch (error) {
   188|    console.log('[ChatScreen] Failed to normalize outbound text:', (error as Error)?.message ?? 'Unknown error');
   189|    return '';
   190|  }
