   193|function hasStructuredInternalRows(text: string): boolean {
   194|  const rows = text
   195|    .split('\n')
   196|    .map((line) => line.trim())
   197|    .filter((line) => line.length > 0)
   198|    .map((line) => {
   199|      const separatorIndex = line.indexOf(':');
   200|      if (separatorIndex <= 0) {
   201|        return null;
   202|      }
   203|      return line.slice(0, separatorIndex).trim().toLowerCase();
   204|    })
   205|    .filter((label): label is string => label !== null);
   206|
   207|  return rows.length >= 3 && rows.includes('result') && (rows.includes('evidence') || rows.includes('operator action log'));
   208|}
